'use strict';

// MODULES //

var tape = require( 'tape' );
var hasOwnProp = require( '@stdlib/assert/has-own-property' );
var isUndefined = require( '@stdlib/assert/is-undefined' );
var hasProp = require( '@stdlib/assert/has-property' );
var isString = require( '@stdlib/assert/is-string' );
var Title = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof Title, 'function', 'main export is a function' );
	t.end();
});

tape( 'the constructor returns an instance which has a `subtitleFont` property', function test( t ) {
	var v;

	v = new Title();
	t.strictEqual( hasOwnProp( v, 'subtitleFont' ), false, 'returns expected value' );
	t.strictEqual( hasProp( v, 'subtitleFont' ), true, 'returns expected value' );
	t.strictEqual( isUndefined( v.subtitleFont ), true, 'returns expected value' );

	v = new Title({
		'subtitleFont': 'Arial'
	});
	t.strictEqual( isString( v.subtitleFont ), true, 'returns expected value' );

	t.end();
});

tape( 'the constructor throws an error if provided an invalid `subtitleFont` option', function test( t ) {
	var values;
	var i;

	values = [
		5,
		NaN,
		null,
		true,
		false,
		[],
		{},
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), Error, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			var title = new Title({ // eslint-disable-line no-unused-vars
				'subtitleFont': value
			});
		};
	}
});

tape( 'the constructor returns an instance having a `subtitleFont` property which throws an error if set to an invalid value', function test( t ) {
	var values;
	var i;

	values = [
		5,
		NaN,
		null,
		true,
		false,
		[],
		{},
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			var title = new Title();
			title.subtitleFont = value;
		};
	}
});

tape( 'the constructor returns an instance having a `subtitleFont` property', function test( t ) {
	var title;

	title = new Title();
	t.strictEqual( isUndefined( title.subtitleFont ), true, 'returns expected value' );

	title = new Title({
		'subtitleFont': 'Arial'
	});
	t.strictEqual( title.subtitleFont, 'Arial', 'returns expected value' );

	title = new Title({
		'subtitleFont': 'Sans'
	});
	t.strictEqual( title.subtitleFont, 'Sans', 'returns expected value' );

	t.end();
});

tape( 'the constructor returns an instance having a `subtitleFont` property which can be set to a valid method', function test( t ) {
	var title;

	title = new Title();

	title.subtitleFont = 'Arial';
	t.strictEqual( title.subtitleFont, 'Arial', 'returns expected value' );

	title.subtitleFont = 'Sans';
	t.strictEqual( title.subtitleFont, 'Sans', 'returns expected value' );

	t.end();
});

tape( 'the constructor returns an instance which emits an event when the `subtitleFont` property is set to a new value', function test( t ) {
	var title;
	var count;

	title = new Title();
	count = 0;

	title.on( 'change', onChange );

	title.subtitleFont = 'Sans';
	t.strictEqual( count, 1, 'returns expected value' );

	title.subtitleFont = 'Arial';
	t.strictEqual( count, 2, 'returns expected value' );

	// Setting to the same value should not emit an event:
	title.subtitleFont = 'Arial';
	t.strictEqual( count, 2, 'returns expected value' );

	t.end();

	function onChange() {
		count += 1;
	}
});
